const legacyIds={"1-2":{"하늘이 열린 이야기, 개천절":"gaecheon-1-2-unit-00","개천절은 언제일까요?":"gaecheon-1-2-unit-01","‘개천’의 뜻":"gaecheon-1-2-unit-02","영상으로 듣는 단군 이야기":"gaecheon-1-2-unit-03","곰과 범의 이야기":"gaecheon-1-2-unit-04","이야기를 차례대로 말해요":"gaecheon-1-2-unit-05","개천절에는 무엇을 할까요?":"gaecheon-1-2-unit-06","홍익인간, 널리 이롭게":"gaecheon-1-2-unit-07","도와줄까? 역할놀이":"gaecheon-1-2-unit-08","태블릿으로 생각 잇기":"gaecheon-1-2-unit-09","그림을 고르세요":"gaecheon-1-2-unit-10","날짜 카드":"gaecheon-1-2-unit-11","함께 이로운 행동":"gaecheon-1-2-unit-12","오늘의 배움 한 문장":"gaecheon-1-2-unit-13"},"3-4":{"하늘이 열린 이야기, 나라를 생각하는 날":"gaecheon-3-4-unit-00","개천절은 언제일까요?":"gaecheon-3-4-unit-01","‘개천’의 뜻":"gaecheon-3-4-unit-02","이야기 ① 하늘에서 내려온 환웅":"gaecheon-3-4-unit-03","이야기 ② 곰과 범의 약속":"gaecheon-3-4-unit-04","이야기 ③ 단군왕검과 조선":"gaecheon-3-4-unit-05","이야기 속에 숨은 뜻":"gaecheon-3-4-unit-06","이야기는 어디에 적혀 있을까?":"gaecheon-3-4-unit-07","개천절은 어떻게 국경일이 되었을까?":"gaecheon-3-4-unit-08","홍익인간, 널리 이롭게":"gaecheon-3-4-unit-09","우리 반 홍익인간 약속 카드":"gaecheon-3-4-unit-10","태블릿으로 생각 잇기":"gaecheon-3-4-unit-11","확인 01":"gaecheon-3-4-unit-12","확인 02":"gaecheon-3-4-unit-13","확인 03":"gaecheon-3-4-unit-14","확인 04":"gaecheon-3-4-unit-15","오늘의 배움 한 문장":"gaecheon-3-4-unit-16"},"5-6":{"나라의 시작을 어떻게 기억할까":"gaecheon-5-6-unit-00","10월 3일은 어디에서 왔을까?":"gaecheon-5-6-unit-01","『삼국유사』라는 기록":"gaecheon-5-6-unit-02","원문으로 읽는 단군 이야기":"gaecheon-5-6-unit-03","일연은 왜 이 이야기를 남겼을까":"gaecheon-5-6-unit-04","전해지는 이야기":"gaecheon-5-6-unit-05","법으로 짐작하는 고조선 사회":"gaecheon-5-6-unit-06","유물이 알려 주는 것":"gaecheon-5-6-unit-07","주장에 근거 붙이기":"gaecheon-5-6-unit-08","홍익인간, 널리 이롭게":"gaecheon-5-6-unit-09","홍익인간 실천 제안서":"gaecheon-5-6-unit-10","태블릿으로 생각 잇기":"gaecheon-5-6-unit-11","자료 판단 01":"gaecheon-5-6-unit-12","자료 판단 02":"gaecheon-5-6-unit-13","자료 판단 03":"gaecheon-5-6-unit-14","자료 판단 04":"gaecheon-5-6-unit-15","가치 적용 05":"gaecheon-5-6-unit-16","오늘의 배움 한 문장":"gaecheon-5-6-unit-17"}};
for(const [grade,g]of Object.entries(grades))g.slides.forEach(s=>{s.id||=legacyIds[grade][s.title];if(!s.id)throw Error(`새 활동에 id가 필요합니다: ${grade}/${s.title}`)});
const artifact={file:'bronze-dagger-songgukri.jpg',title:'부여 송국리 출토 비파형 동검 · 신수3094',alt:'칼몸 아래쪽이 넓고 양옆으로 돌기가 있는 송국리 출토 비파형 동검 실제 사진',credit:'국립중앙박물관 · 공공누리 제1유형 출처표시 · 사진 원본',url:'https://www.museum.go.kr/MUSEUM/contents/M0502000000.do?relicId=2040&schM=view&searchId=search'};
for(const g of Object.values(grades))for(const s of g.slides){if(s.kind==='evidence'){s.artifact=artifact;s.title='실제 동검 사진에서 찾은 단서';s.question='사진의 모양과 소장품 정보를 보고, 알 수 있는 것과 확인할 수 없는 것을 말해요.';s.answer='실제 출토 유물의 사진이에요. 모양·재질·출토지는 청동기 기술과 문화를 탐구할 단서예요. 이 유물이 나온 곳을 바로 고조선의 국경으로 정하거나 단군의 정확한 건국 날짜를 알아낼 수는 없어요.';s.note='국립중앙박물관 신수3094. 부여 송국리 돌널무덤 출토, 동합금. 사진과 소장품 정보로 관찰한 점을 나누어 말합니다. 이 한 점으로 전체 문화 분포나 고조선의 확정된 국경을 그리지 않습니다. 그림과 사진의 성격도 구별합니다.';}
if(s.kind==='evidence'&&s.links?.length)s.links[0]={title:'국립중앙박물관 · 송국리 출토 동검 소장품',url:artifact.url};
if(s.kind==='quiz'&&s.question.includes('분포만으로')){s.artifact=artifact;s.question='이 동검 사진과 소장품 정보로 알 수 없는 것은?';s.choices=['단군의 정확한 건국 날짜','동합금이라는 재질','이 유물의 출토지','칼몸의 모양'];s.answer='사진과 소장품 정보는 모양·재질·출토지를 알려 주지만 정확한 고대 건국 날짜의 증거는 아니에요.';}}
GC_SOURCES.push({title:'국립중앙박물관 · 송국리 출토 비파형 동검 신수3094 (사진·공공누리 제1유형)',url:artifact.url});
const storyResource=window.LEARNING_RESOURCES.story;
const readingResource=window.LEARNING_RESOURCES.samguk;
const originalReading=grades['5-6'].slides.find(s=>s.kind==='reading');
originalReading.cards=readingResource.quotes.map(q=>({title:q.label,text:q.original,sub:'수업용 풀이 · '+q.paraphrase}));
originalReading.links=[{title:'삼국유사 원문·번역 전체 보기',url:readingResource.url}];
originalReading.question='① 100일은 어떤 약속의 기간일까요? ② 삼칠일(21일)은 어떤 변화까지 걸린 기간으로 적혀 있나요? 두 숫자가 가리키는 일을 비교해요.';
originalReading.note='짧은 한문 발췌와 수업용 풀이를 나란히 읽습니다. 100일 약속과 21일 변화 서술을 구분하고, 이 기록으로 실제 건국 날짜를 확인할 수 있는 것은 아님을 설명합니다. 한자를 소리 내어 읽게 하지 않습니다.';
originalReading.answer='100일은 햇빛을 보지 않는 약속의 기간, 삼칠일(21일)은 이야기 속 곰의 변화까지 걸린 기간으로 서술됩니다. 두 숫자가 가리키는 일을 구별해요.';
const youngSequence=grades['1-2'].slides.find(s=>s.kind==='sequence');
youngSequence.sequence=storyResource.cards.map(c=>({image:c.image,text:c.text,alt:c.alt}));
youngSequence.sequenceOrder=storyResource.order;
youngSequence.question='네 그림을 이야기 순서대로 말해 볼까요? 1번은 어느 그림일까요?';
youngSequence.answer='환웅이 내려옴 → 곰과 범의 약속 → 웅녀가 된 곰 → 단군과 고조선. 모두 전해지는 이야기 속 장면이에요.';
youngSequence.note='네 카드의 사건을 가리키며 이야기하게 합니다. 웅녀 카드의 겹친 곰은 변화 전 모습을 떠올리는 그림 표현이며 두 인물이 함께 있었다는 뜻이 아닙니다. 실제 인물·복식·유적의 복원이 아닙니다.';
for(const s of grades['3-4'].slides){if(s.kind==='story'&&s.title.includes('환웅'))s.image=storyResource.cards[0].image;if(s.kind==='story'&&s.title.includes('약속'))s.image=storyResource.cards[1].image;if(s.kind==='story'&&s.title.includes('단군'))s.image=storyResource.cards[3].image;}
grades['3-4'].objectives=['개천절 날짜와 기념하는 뜻을 설명한다','문헌과 유물이 알려 주는 점과 확인하지 못하는 점을 비교한다','상대의 뜻을 묻는 도움 약속을 만들고 이유를 설명한다'];
window.GAECHEON_DATA={grades,sources:GC_SOURCES,storyCards:storyResource.cards,storyOrder:storyResource.order};
